algorithms.pseudocode:
Input: S subset Z/aZ, coprime a, b
Output: Lift_L(S) subset Z/(ab)Z

lifted <- empty set
for x = 0 to ab - 1:
    if x mod a in S:
        lifted <- lifted union {x}
return lifted

Complexity: Time O(ab), Space O(|S| * b)
Property: conductance(Lift(S), ab) = conductance(S, a)
